["customDuration"] = "function()\n    -- calculate timeout based on next tick\n    return aura_env.nextTick - GetTime(), aura_env.nextTick\nend",
["spellIds"] = {
},
["custom"] = "function(event ,target, guid, spellID)\n    local time = GetTime()\n    \n    -- only trigger if spell cost mana\n    if aura_env.manaChange >= 0 then\n        return false\n    end\n    \n    -- calculate tick delay depending on when in the tick cycle a spell was cast\n    local manaRegenBlockEnd = time + 5 - aura_env.config.TOLERANCE\n    local tickDiff = manaRegenBlockEnd - aura_env.lastManaTick\n    \n    local magicNumber -- try to guess tick delay\n    if tickDiff < 8 then\n        magicNumber = 2 + aura_env.config.TICKOFFSET / 2\n    else\n        magicNumber = 2 + aura_env.config.TICKOFFSET\n    end\n    \n    local tickDelay = magicNumber - (tickDiff % (magicNumber))\n    aura_env.nextTick = time + 5 - aura_env.config.TOLERANCE + tickDelay \n    return true\nend",
["subeventSuffix"] = "_CAST_START",
["events"] = "UNIT_SPELLCAST_SUCCEEDED:player",
["names"] = {
},
["unit"] = "player",
["custom_hide"] = "timed",
},
["untrigger"] = {
},
},
{
["trigger"] = {
["unit"] = "player",
["type"] = "custom",
["custom"] = "function(event, target, type)\n    local time = GetTime()\n    \n    if not type == \"MANA\" then\n        return false\n    end\n    \n    local currentMana = UnitPower(\"player\" , Enum.PowerType.Mana)\n    local maxMana =  UnitPowerMax(\"player\", Enum.PowerType.Mana)\n    \n    -- save mana changes, used in spell trigger\n    aura_env.manaChange = currentMana - aura_env.prevMana\n    aura_env.prevMana = currentMana\n    \n    -- dont trigger if mana is full\n    if currentMana >= maxMana then\n        return false\n    end\n    \n    -- dont trigger if mana is not increasing\n    if aura_env.manaChange <= 0 then\n        return false\n    end\n    \n    -- only trigger if next tick is within expected time frame to prevent triggering for \n    -- other mana sources\n    if aura_env.nextTick <= time then\n        aura_env.lastManaTick = time\n        aura_env.nextTick = time + 2 - aura_env.config.TOLERANCE\n        return true\n    else\n        return false\n    end\nend",
